sys_script_include.script:
var discoveryHealthKPI = Class.create();
discoveryHealthKPI.prototype = {
    initialize: function() {
        this.healthIndicators = {
            schedule_adherence: 0.25,
            error_rates: 0.25,
            completion_rates: 0.25,
            data_quality: 0.25
        };

        // Sample historical data
        this.historicalData = {
            lastMonth: {
                schedule_adherence: 0.92,
                error_rates: 0.05,
                completion_rates: 0.88,
                data_quality: 0.95
            },
            thisMonth: {
                schedule_adherence: 0.94,
                error_rates: 0.03,
                completion_rates: 0.90,
                data_quality: 0.96
            }
        };
    },

    calculate: function() {
        return {
            overall_health: this._calculateOverallHealth(),
            trend_analysis: this._analyzeTrends(),
            bottleneck_analysis: this._analyzeBottlenecks(),
            recommendation_engine: this._generateRecommendations()
        };
    },

    _calculateOverallHealth: function() {
        var health = {};
        // Calculate schedule adherence
        health.schedule_adherence = this._calculateScheduleAdherence();
        // Calculate error rates
        health.error_rates = this._calculateErrorRates();
        // Calculate completion rates
        health.completion_rates = this._calculateCompletionRates();
        // Calculate data quality
        health.data_quality = this._calculateDataQuality();
        return this._weightedScore(health);
    },

    _calculateScheduleAdherence: function() {
        return this.historicalData.thisMonth.schedule_adherence;
    },

    _calculateErrorRates: function() {
        return 1 - this.historicalData.thisMonth.error_rates; // Convert to success rate
    },

    _calculateCompletionRates: function() {
        return this.historicalData.thisMonth.completion_rates;
    },

    _calculateDataQuality: function() {
        return this.historicalData.thisMonth.data_quality;
    },

    _weightedScore: function(health) {
        return {
            score: (
                health.schedule_adherence * this.healthIndicators.schedule_adherence +
                health.error_rates * this.healthIndicators.error_rates +
                health.completion_rates * this.healthIndicators.completion_rates +
                health.data_quality * this.healthIndicators.data_quality
            ),
            components: health
        };
    },

    _analyzeTrends: function() {
        return {
            schedule_adherence: {
                trend: this.historicalData.thisMonth.schedule_adherence - this.historicalData.lastMonth.schedule_adherence,
                status: "improving"
            },
            error_rates: {
                trend: this.historicalData.lastMonth.error_rates - this.historicalData.thisMonth.error_rates,
                status: "improving"
            },
            completion_rates: {
                trend: this.historicalData.thisMonth.completion_rates - this.historicalData.lastMonth.completion_rates,
                status: "improving"
            },
            data_quality: {
                trend: this.historicalData.thisMonth.data_quality - this.historicalData.lastMonth.data_quality,
                status: "improving"
            }
        };
    },

    _analyzeBottlenecks: function() {
        var bottlenecks = [];
        // Analyze network bottlenecks
        bottlenecks = bottlenecks.concat(this._analyzeNetworkBottlenecks());
        // Analyze credential bottlenecks
        bottlenecks = bottlenecks.concat(this._analyzeCredentialBottlenecks());
        // Analyze resource bottlenecks
        bottlenecks = bottlenecks.concat(this._analyzeResourceBottlenecks());
        return bottlenecks;
    },

    _analyzeNetworkBottlenecks: function() {
        return [{
            type: "network",
            severity: "low",
            description: "Minor latency issues detected",
            impact: "Minimal impact on schedule adherence"
        }];
    },

    _analyzeCredentialBottlenecks: function() {
        return [{
            type: "credentials",
            severity: "medium",
            description: "Expired credentials detected for 2 systems",
            impact: "Moderate impact on completion rates"
        }];
    },

    _analyzeResourceBottlenecks: function() {
        return [{
            type: "resource",
            severity: "high",
            description: "CPU utilization above 90%",
            impact: "Significant impact on processing speed"
        }];
    },

    _generateRecommendations: function() {
        return [
            {
                priority: "high",
                area: "resources",
                recommendation: "Increase CPU allocation",
                expected_impact: "25% improvement in processing speed"
            },
            {
                priority: "medium",
                area: "credentials",
                recommendation: "Implement automated credential renewal",
                expected_impact: "50% reduction in credential-related delays"
            },
            {
                priority: "low",
                area: "network",
                recommendation: "Optimize network routes",
                expected_impact: "10% reduction in latency"
            }
        ];
    }
};
